class complex {
    double re, im; // 메모리 표현: double 두 개
public:
    complex(double r, double i) :re{r}, im{i} {} // 두 스칼라를 이용해 complex 생성
    complex(double r) :re{r}, im{0} {} // 스칼라 하나를 이용해 complex 생성
    complex() :re{0}, im{0} {} // 기본 complex: {0,0}

    double real() const { return re; }
    void real(double d) { re=d; }
    double imag() const { return im; }
    void imag(double d) { im=d; }

    complex& operator+=(complex z)
    {
        re+=z.re; // re와 im에 더하기
        im+=z.im;
        return *this; // 결과 반환
    }
    complex& operator-=(complex z)
    {
        re-=z.re;
        im-=z.im;
        return *this;
    }

    complex& operator*=(complex); // 클래스 밖의 어딘가에서 정의
    complex& operator/=(complex); // 클래스 밖의 어딘가에서 정의
};

class Vector {
public:
    Vector(int s) :elem{new double[s]}, sz{s} // 생성자: 자원 획득
    {
        for (int i=0; i!=s; ++i) // 요소 초기화
            elem[i]=0;
    }

    ~Vector() { delete[] elem; } // 소멸자 : 자원 해제

    double& operator[](int i);
    int size() const;
private:
    double* elem; // elem은 double요소 sz개를 가리킴
    int sz;
};

Vector::Vector(std::initializer_list<double> lst) // 초깃값 목록 초기화
    :elem{new double[lst.size()]}, sz{static_cast<int>(lst.size())}
{
    copy(lst.begin(),lst.end(),elem); // lst를 elem에 복사(12.6절)
}

class Container {
public:
    virtual double& operator[](int) = 0; // 순수 가상 함수
    virtual int size() const = 0; // const 멤버 함수(4.2.1절)
    virtual ~Container() {} // 소멸자(4.2.2절)
};

void use(Container& c)
{
    const int sz = c.size();
    for (int i=0; i!=sz; ++i)
        cout << c[i] << '\n';
}

class Vector_container :public Container { // Vector_container가 Container를 구현
public:
    Vector_container(int s) : v(s) { } // 요소들의 벡터
    ~Vector_container() {}

    double& operator[](int i) override { return v[i]; }
    int size() const override { return v.size(); }
private:
    Vector v;
};

